// Generated by scripts/gen-ai-schema.ts from prisma/schema.prisma — do not edit.
export const AI_SCHEMA_TEXT = "// Production Planning & Tracking — data model\n// Mirrors the Excel workbook sheets (Plans, Plan Orders, Daily Handover, Lists).\n// Business values (BOM, item, dept) are English; UI is Arabic RTL.\n\n// Weekly plan header. startDate is ALWAYS entered by the user, never trusted\n// from the imported file (Planning copies stale dates between sheets).\nmodel Plan {\n  planNo    Int      @id\n  startDate DateTime // real oven-week start date (day 0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  orders    PlanOrder[]\n  schedules PlanSchedule[]\n}\n\n// One row per MO x item (Plan Orders sheet, cols A:J).\n// requiredQty = full order size; targetQty = what to make THIS week\n// (balance carried in + this week's grid); plannerBalance = remark-declared balance.\nmodel PlanOrder {\n  id             Int     @id @default(autoincrement())\n  planNo         Int\n  bom            String\n  soi            String?\n  mo             String\n  description    String?\n  item           String // CF | TC | TN | CB\n  requiredQty    Float   @default(0)\n  plannerBalance Float? // parsed from REMARK \"...BALANCE...\"; null if no balance remark\n  targetQty      Float   @default(0)\n  remark         String?\n\n  plan Plan @relation(fields: [planNo], references: [planNo], onDelete: Cascade)\n\n  @@unique([planNo, mo, item])\n  @@index([planNo])\n  @@index([bom])\n}\n\n// Flat schedule (Plans sheet, cols A:H). One row per BOM/MO x item x oven date.\n// ovenDate is the OVEN loading date; process due date = ovenDate - lead days.\nmodel PlanSchedule {\n  id          Int      @id @default(autoincrement())\n  planNo      Int\n  bom         String\n  soi         String?\n  mo          String\n  description String?\n  item        String // CF | TC | TN | CB\n  ovenDate    DateTime\n  qty         Float    @default(0)\n\n  plan Plan @relation(fields: [planNo], references: [planNo], onDelete: Cascade)\n\n  @@index([planNo])\n  @@index([bom])\n  @@index([ovenDate])\n}\n\n// Shop-floor handover log (Daily Handover sheet, cols A:F).\n// \"Done\" everywhere = Welding output. Cut gates Welding.\n// Rows are IMMUTABLE once written for reallocation purposes; edits are audited.\nmodel HandoverEntry {\n  id     Int      @id @default(autoincrement())\n  date   DateTime // work date (day-only granularity)\n  dept   String // Cut | Welding\n  bom    String // raw as entered (may be auto-corrected at entry time)\n  bomRaw String? // original text before normalization, if corrected\n  mo     String? // manufacturing order, when recorded per-MO (execution sheet)\n  item   String // CF | TC | TN | CB\n  qty    Float\n  planNo Int\n\n  // The machine the pieces were finished on, when the record came off a\n  // machine card — nothing else can say it. It is what lets the app MEASURE\n  // how long an item really takes on a machine, against the hours the shift\n  // log put on it, instead of only holding the figure somebody typed.\n  machineId Int?\n  machine   Machine? @relation(fields: [machineId], references: [id], onDelete: SetNull)\n\n  // audit\n  source    String   @default(\"manual\") // manual | import | seed | reallocation\n  note      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  createdBy String?\n\n  @@index([planNo])\n  @@index([date])\n  @@index([bom])\n  @@index([dept])\n  // the chain check, the tracker's totals and the trace all read one order's\n  // item at one stage\n  @@index([mo, item, dept])\n  @@index([machineId])\n}\n\n// Explicit, reviewable excess-reallocation transaction (replaces the VBA's\n// silent edit of the handover log). Raw HandoverEntry rows stay immutable;\n// approved moves are applied as a derived adjustment layer.\n// Master order registry — fed by the MONTHLY plan. Import upserts by MO:\n// existing MOs are left untouched, new MOs are added. This is the general\n// orders list; weekly plans only contribute delivery schedules.\nmodel MasterOrder {\n  id               Int       @id @default(autoincrement())\n  mo               String    @unique\n  // Which of the plant's two products this order is — a transformer (TR) or\n  // an LV panel (LV). Stamped by the plan import it came from and never\n  // inferred from the order's shape. Every screen shows ONE line at a time.\n  line             String    @default(\"TR\")\n  soi              String?\n  urgent           Boolean   @default(false)\n  customer         String?\n  fgCode           String?\n  bom              String\n  kva              String?\n  rating           String?\n  secItem          String?\n  // The LV plan's own columns. `product` is the panel type (LSS / USS);\n  // `ospEncloser` the enclosures bought outside rather than made here;\n  // `materialsRemarks` the sheet's second remarks column, about parts.\n  product          String?\n  ospEncloser      Float     @default(0)\n  materialsRemarks String?\n  // Which of the line's plans brought the order: \"\" the line's main plan\n  // (transformers / LV panels), \"MB\" the LV meter boxes' own sheet. A plan's\n  // import revises and takes off the month only the orders of its own plan.\n  family           String    @default(\"\")\n  planQty          Float     @default(0)\n  // A plan import that brings a DIFFERENT qty for an order already in the\n  // registry never overwrites planQty: the sheet's figure waits here, with the\n  // plan that brought it, until the planner uses it or keeps the old one.\n  pendingPlanQty   Float?\n  pendingQtyMonth  String?\n  pendingQtyAt     DateTime?\n  // The order's spec columns, shown on the tracker. NONE of them is imported:\n  // the monthly sheet does not carry them in a form the import can trust, so\n  // the planner types them on the tracker and a re-import leaves them alone.\n  // Fins sits beside the components (it is one of them, welded on the tank);\n  // the rest sit beside KVA.\n  fins             String?\n  crcSize          String? // \"CRC Size\" — 900, \"-\", …\n  colorRal         String?\n  sfm              String?\n  remarks          String?\n  source           String? // which monthly plan (month label) FIRST added it\n  // EVERY monthly plan the MO appeared in (CSV of month labels) — a carried-over\n  // order shows under each of its months in the tracker filter, with a badge\n  months           String    @default(\"\")\n  status           String    @default(\"open\") // open | closed\n  // OSP — quantities outsourced per component (made outside, not by our depts).\n  // They never appear in the dept worklists and count as covered in the tracker.\n  ospCF            Float     @default(0)\n  ospTC            Float     @default(0)\n  ospTN            Float     @default(0)\n  ospCB            Float     @default(0)\n  // Components this order does NOT need at all (CSV of CF/TC/TN/CB). The plan\n  // sheets can't express this — it is set manually on the tracker.\n  excludedItems    String?\n  // Components this order needs although the KVA/rating rule says otherwise\n  // (CSV, in practice AR/MB). The planner's own say over the rule: together\n  // with excludedItems, the six components are his to switch on or off.\n  includedItems    String?\n  // Marked IMPORTANT by the admin: shows in a dedicated priority table on top\n  // of every dept worklist until its work is done.\n  priority         Boolean   @default(false)\n  // ON HOLD — the planner paused this order: it stays open on the tracker\n  // (tinted, with the reason) but leaves every worklist queue and the ETA\n  // until released. `holdAt` set = on hold.\n  holdAt           DateTime?\n  holdNote         String?\n  holdBy           String?\n  closedAt         DateTime?\n  // reopened by hand after it closed by itself: it no longer closes by itself\n  // — until someone closes it again\n  autoCloseOff     Boolean   @default(false)\n  // when it closed by itself (finished and all closed in Odoo); null when a\n  // person or an import closed it\n  autoClosedAt     DateTime?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  @@index([bom])\n  @@index([status])\n  @@index([line])\n}\n\n// Admin date override on a fabrication-worklist line (BOM × MO × item).\n// origISO is the line's ORIGINAL promised delivery date (\"\" = the line had no\n// date — a date-less row scheduled by the admin). A date-less line may carry\n// SEVERAL rows (one per chosen date), each with a QTY taken from the open\n// pool; qty null = the whole line (legacy / dated-row moves). baseDone\n// snapshots the dept output at scheduling time so LATER output consumes the\n// admin's tranches earliest-first without double-counting what was already\n// done. Reverting = deleting the row: the plan's own date (or the pool)\n// resurfaces. If a weekly re-import changes the line's dates, the override no\n// longer matches its origISO and silently stops applying.\nmodel WorklistDateOverride {\n  id        Int      @id @default(autoincrement())\n  bom       String\n  mo        String\n  item      String // CF | TC | TN | CB\n  origISO   String   @default(\"\") // original delivery ISO date; \"\" = was date-less\n  newDate   DateTime // admin-chosen delivery (oven) date\n  qty       Float? // pieces scheduled on that date (null = the whole line)\n  baseDone  Float    @default(0) // dept output when scheduled — consumption baseline\n  createdBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // one row per (line, original date, chosen date); dated-row moves keep a\n  // single row per original tranche via delete-then-create in the action\n  @@unique([bom, mo, item, origISO, newDate])\n}\n\n// A worklist line the ADMIN removed from view (any dept's worklist). The line\n// itself (plans, logs, registry) is untouched — restoring = deleting this row.\nmodel WorklistLineHide {\n  id        Int      @id @default(autoincrement())\n  dept      String // Cut | Welding | Painting\n  bom       String\n  mo        String // \"\" for BOM-level queue lines\n  item      String // CF | TC | TN | CB\n  createdBy String?\n  createdAt DateTime @default(now())\n\n  @@unique([dept, bom, mo, item])\n}\n\n// An order sent DOWN from the Plan Tracker to a dept's worklist with a chosen\n// quantity per item (≤ the order's unfinished remainder), to be scheduled and\n// worked there. Admin-managed; removing the row takes the line off the list.\nmodel WorklistPush {\n  id        Int      @id @default(autoincrement())\n  dept      String // Cut | Welding | Painting\n  bom       String\n  mo        String\n  item      String // CF | TC | TN | CB\n  qty       Float\n  baseDone  Float    @default(0) // dept output when pushed — output recorded after consumes the push\n  createdBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([dept, mo, item])\n}\n\n// Factory calendar — non-working days besides Fridays (public holidays,\n// planned shutdowns). These days carry no production target.\nmodel Holiday {\n  id        Int      @id @default(autoincrement())\n  date      DateTime @unique // day-only granularity\n  name      String\n  createdAt DateTime @default(now())\n}\n\n// A piece sent back UPSTREAM: e.g. Welding discovers a \"finished\" cut piece is\n// incomplete and returns it to Cut. The quantity is deducted from the upstream\n// department's ledger via a linked negative HandoverEntry (source \"return\"),\n// and the row stays in the upstream dept's Returns table until re-delivered.\nmodel ReturnEntry {\n  id         Int      @id @default(autoincrement())\n  date       DateTime\n  fromDept   String // who returned it (Welding | Painting)\n  toDept     String // who gets it back (Cut | Welding)\n  bom        String\n  mo         String?\n  item       String // CF | TC | TN | CB\n  qty        Float\n  reason     String\n  status     String   @default(\"open\") // open | resolved (re-delivered)\n  handoverId Int? // the linked negative ledger entry\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([toDept, status])\n}\n\n// Shop-floor note on a queue line (welding/painting worklists): free text +\n// photos documenting the real state of an order — missing parts, defects,\n// disputed \"done\" claims. Photos live under public/uploads/notes.\nmodel QueueNote {\n  id        Int      @id @default(autoincrement())\n  bom       String\n  mo        String? // null for BOM-level legacy lines\n  item      String // CF | TC | TN | CB\n  dept      String // Welding | Painting — where the note was raised\n  text      String\n  photos    String? // JSON array of public URL paths\n  status    String   @default(\"open\") // open | resolved\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([bom, mo, item])\n  @@index([status])\n}\n\n// Application account. Admin manages accounts and assigns granular permission\n// keys (see lib/domain/permissions.ts) from the in-app Users page.\nmodel User {\n  id               Int                @id @default(autoincrement())\n  name             String\n  active           Boolean            @default(true)\n}\n\n// Global settings (Lists!J2:J5). Single row (id = 1).\nmodel Settings {\n  id              Int @id @default(1)\n  leadCut         Int @default(4)\n  leadWeld        Int @default(1)\n  capacityPerItem Int @default(27)\n  dailyTarget     Int @default(27)\n  // First recording day for automatic Odoo allocation (YYYY-MM-DD).\n  // Null until chosen: older imported orders must not silently consume new closings.\n  odooTrackingFrom String?\n\n  // Master switch for tracking tanks PIECE BY PIECE — serials, the leak-test\n  // stage, painting by selection and the barcode tab. OFF by default: the\n  // plant records tanks as quantities, exactly as it always did, until someone\n  // decides the shop floor is ready to work off the serials. Turning it off\n  // again is always safe — the tanks already recorded stay in the database and\n  // pick up where they left off when it comes back on.\n  tankTracking Boolean @default(false)\n\n  // Master switch for planning work onto MACHINES: the machine board and the\n  // Machine column on the worklists, the machine sheets, and the Floor view.\n  // OFF until the plant plans by machine — the assignments already made stay\n  // saved and come back when it is turned on.\n  machinePlanning Boolean @default(false)\n\n  // The plant's two shifts and the overtime the \"+OT\" button adds, in hours.\n  // Editable: a roster changes (Ramadan, a second shift starting), and every\n  // man-hour the app counts — the shift log, a machine's crew, the day's\n  // capacity — is measured with these.\n  shiftShortH Float @default(8)\n  shiftLongH  Float @default(8)\n  overtimeH   Float @default(3)\n  nightOvertimeH Float @default(3)\n}\n\n// ---- Standard man-hours (the engineering timings sheet, editable in Admin →\n// Standard Times; seeded by migration from \"Final Timings 3rd industrial\") ----\n\n// Hours ONE tank of a KVA class costs each stage. The per-component split is\n// derived from the sheet's engineering shares at read time (lib/domain/stdEngine).\nmodel StdTime {\n  id        Int      @id @default(autoincrement())\n  kva       Int      @unique // KVA class: 100, 200, ... (admin can add classes)\n  cutMh     Float // laser + bending + fin folding\n  weldMh    Float\n  shbMh     Float\n  paintMh   Float\n  updatedAt DateTime @default(now()) @updatedAt\n}\n\n// The LV panels' standard hours per UNIT and stage, from the timings sheet's LV\n// tab. An order finds its row by FG code, or through its SEC item — the\n// plan's FG code (FG-SUA-AS-AA-000004) is not the sheet's (FG-SUSA-8569105),\n// but the SEC item 908569105 is the same panel. Steel stages only: punching /\n// laser cutting, bending, welding, shot blast and the paint line; totalH is\n// the sheet's whole per-unit figure, assembly and wiring included.\nmodel LvStdTime {\n  id          Int      @id @default(autoincrement())\n  fg          String   @unique // as the sheet writes it: FG-SUSA-8569105\n  description String?\n  kind        String   @default(\"USS\") // USS | MB (meter box) | FP (feeder pillar)\n  cutH        Float\n  bendH       Float\n  weldH       Float\n  shbH        Float\n  paintH      Float\n  totalH      Float?\n  updatedAt   DateTime @default(now()) @updatedAt\n}\n\n// FG code → KVA class (the sheet's product table). The FG map outranks the\n// order's numeric KVA — the sheet files in-between sizes inconsistently.\nmodel StdFgMap {\n  id  Int    @id @default(autoincrement())\n  fg  String @unique // normalized: uppercase alphanumerics only\n  kva Int\n}\n\n// Available capacity per production stage, in man-hours per WORKING DAY —\n// what the plan's required hours are measured against.\nmodel StageCapacity {\n  id        Int      @id @default(autoincrement())\n  dept      String   @unique // Cut | Welding | ShotBlast | Painting\n  mhPerDay  Float\n  updatedAt DateTime @default(now()) @updatedAt\n}\n\n// Man-hours a stage ACTUALLY worked on one day (people who showed up × their\n// hours), entered by the admin. Compared against the std-hours the ledger says\n// that day EARNED, it calibrates the standard times to this plant's real pace.\nmodel DeptDayHours {\n  id         Int      @id @default(autoincrement())\n  date       DateTime // day-only granularity\n  dept       String // Cut | Welding | ShotBlast | Painting\n  hours      Float\n  // The quick entry: heads present × hours each. Null on a day summed from\n  // the per-worker roster.\n  people     Int?\n  hoursEach  Float?\n  source     String   @default(\"roster\") // roster | quick\n  recordedBy String?\n  updatedAt  DateTime @default(now()) @updatedAt\n\n  @@unique([date, dept])\n}\n\n// ---- Machines and the shift log ----\n\n// One machine (or line) of a department — a laser, a punch, the fins press,\n// a paint line, a shot-blast cabinet. `center` groups the ones that do the\n// same work: every laser and punch is \"Cutting\" (a job goes to whichever is\n// free), the fins press is \"Fins\", a paint line is \"Line\". Bending has no\n// machines yet — it is a stage worked by people. The admin keeps the list;\n// the shift log and the worklists only read it.\nmodel Machine {\n  id          Int      @id @default(autoincrement())\n  code        String   @unique // the plant's asset code: B4-10\n  name        String // Bodor 3K watt\n  dept        String // Cut | Welding | ShotBlast | Painting\n  center      String   @default(\"\") // Cutting | Fins | Tubes | RollBlank | Line\n  hoursPerDay Float? // available hours on a working day; null = not set\n  active      Boolean  @default(true)\n  sortOrder   Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  shifts     ShiftEntry[]\n  downtimes  MachineDowntime[]\n  lines      WorklistMachine[]\n  itemTimes  MachineItemTime[]\n  output     HandoverEntry[]\n  manualJobs ManualJob[]\n  sheetCuts  SheetCutLog[]\n  rules      MachineRule[]\n\n  @@index([dept])\n}\n\n// What one machine takes — the planner's own knowledge of the floor, written\n// down so ⚡ Plan follows it: \"the 6 kW laser takes 6 mm and up\", \"the punch\n// does top covers only\", \"keep stainless off B4-09\", \"tanks of 1000 kVA and up\n// go first to B4-10\". `effect`:\n//   only   — the machine takes ONLY work matching one of its \"only\" rules;\n//   never  — it never takes work matching this rule;\n//   prefer — among the machines allowed, it goes first for matching work.\n// Every field given must match; a rule with none matches all work. Thickness\n// and material are read off the line's nesting (the MATERIAL tab): a line\n// matches a thickness range only when every sheet it is cut from is inside it,\n// and a line with no nesting yet does not match a thickness or material rule.\n// A rule taken off stays (inactive), with who took it off.\nmodel MachineRule {\n  id             Int      @id @default(autoincrement())\n  machineId      Int\n  machine        Machine  @relation(fields: [machineId], references: [id], onDelete: Cascade)\n  effect         String // only | never | prefer\n  item           String? // CF | TC | TN | CB | AR | MB | PNL\n  line           String? // TR | LV\n  minThicknessMm Float?\n  maxThicknessMm Float?\n  material       String? // as the MATERIAL tab names it: Steel, Stainless steel …\n  minKva         Int?\n  maxKva         Int?\n  note           String? // the planner's own words for it\n  active         Boolean  @default(true)\n  createdBy      String?\n  updatedBy      String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([machineId, active])\n}\n\n// What ONE piece of an item really costs on ONE machine, in hours — the\n// planner's own figure, from the routing sheet or from watching the floor.\n// Where it is set it OUTRANKS the standard-times estimate for that machine:\n// its queue is priced with it, and the ⚡ planner schedules with it, so a\n// 6 kW laser and a punch stop being treated as the same machine. Left empty,\n// the estimate stands (the stage's standard hours split over the centres the\n// item routes through).\nmodel MachineItemTime {\n  id         Int      @id @default(autoincrement())\n  machineId  Int\n  machine    Machine  @relation(fields: [machineId], references: [id], onDelete: Cascade)\n  item       String // CF | TC | TN | CB | AR | MB\n  hoursPerPc Float\n  setBy      String?\n  updatedAt  DateTime @default(now()) @updatedAt\n\n  @@unique([machineId, item])\n  @@index([machineId])\n}\n\n// One worker's day in one department, as the supervisor records it: present\n// or not, which shift (day or night), overtime on the day shift, and the machine they\n// were on. A worker with no row for a day is NOT SET yet — neither present nor\n// absent; the Shifts tab saves a department's day only once every worker on it\n// has a row (S9 day 07:00–16:00, S11 night 19:00–04:00, optional OT 04:00–07:00, or absent). The\n// day's man-hours per department are summed into DeptDayHours from here.\nmodel ShiftEntry {\n  id         Int      @id @default(autoincrement())\n  date       DateTime // day-only granularity\n  dept       String // Cut | Welding | ShotBlast | Painting\n  workerId   Int\n  worker     Worker   @relation(fields: [workerId], references: [id], onDelete: Cascade)\n  present    Boolean  @default(true)\n  shift      String   @default(\"S9\") // S9 | S11\n  overtimeH  Float    @default(0)\n  machineId  Int?\n  machine    Machine? @relation(fields: [machineId], references: [id], onDelete: SetNull)\n  // The work centre the worker was on that day, where the department has more\n  // than one (Fabrication: Cutting | Bending | Fins — lib/domain/shifts.ts\n  // WORK_CENTRES). The roster offers his section's centre and saves the one\n  // shown; null on other departments and on rows from before centres.\n  center     String?\n  note       String?\n  recordedBy String?\n  updatedAt  DateTime @default(now()) @updatedAt\n\n  @@unique([date, dept, workerId])\n  @@index([date, dept])\n  @@index([workerId])\n  @@index([machineId])\n}\n\n// Hours a machine stood still on a day, and why — the planner's reason a\n// day's load did not land, and the capacity a machine really had.\nmodel MachineDowntime {\n  id         Int      @id @default(autoincrement())\n  date       DateTime\n  machineId  Int?\n  machine    Machine? @relation(fields: [machineId], references: [id], onDelete: Cascade)\n  // An unlisted asset can be logged without creating a schedulable machine.\n  customName   String?\n  customDept   String?\n  customCentre String?\n  // Factory wall-clock times on `date`; a next-day end belongs to this starting day.\n  // Null for historical duration-only records. Timed records keep minute precision.\n  startTime    String? @db.VarChar(5)\n  endTime      String? @db.VarChar(5)\n  endsNextDay  Boolean @default(false)\n  // Open incidents have no end and hours=0 in storage. Readers calculate elapsed time as of now.\n  // An explicit closing date supports repairs spanning multiple days; old records keep their booking.\n  isOpen       Boolean @default(false)\n  endDate      DateTime? @db.Date\n  hours      Float\n  // Why, as one of the plant's codes (lib/domain/downtime.ts) so the stops can\n  // be counted by cause; `reason` keeps the supervisor's own words.\n  reasonCode String?\n  reason     String?\n  recordedBy String?\n  createdAt  DateTime @default(now())\n\n  @@index([date])\n  @@index([machineId])\n  @@index([customDept, customName, date])\n  @@index([isOpen, date])\n}\n\n// The planner's own hours for ONE piece of an item at one work centre, for one\n// KVA class — typed by hand. Where a figure is set it replaces the estimate the\n// standard times split out of the stage total (lib/domain/stdEngine.ts), so\n// every earned hour, load and capacity check in the app is priced with it.\nmodel CenterStdTime {\n  id         Int      @id @default(autoincrement())\n  kva        Int // KVA class, as StdTime\n  item       String // CF | TC | TN | CB | AR | MB\n  center     String // Cutting | Bending | Fins | Welding | ShotBlast | Painting\n  hoursPerPc Float\n  setBy      String?\n  updatedAt  DateTime @default(now()) @updatedAt\n\n  @@unique([kva, item, center])\n}\n\n// Which machine a worklist line is on, and where it stands in that machine's\n// queue — \"this is running on that now\". Keyed like the other worklist\n// layers (dept × bom × mo × item); rank 1 is what the machine is on, the\n// rest wait behind it. Recording output never touches it: a line leaves the\n// board by itself once nothing remains on it.\nmodel WorklistMachine {\n  id        Int      @id @default(autoincrement())\n  dept      String // Cut | Painting\n  bom       String\n  mo        String\n  item      String\n  machineId Int\n  machine   Machine  @relation(fields: [machineId], references: [id], onDelete: Cascade)\n  rank      Int      @default(0)\n  // Running on the machine right now — several lines can be, when the\n  // machine nests or works them together; the rest wait in rank order.\n  running   Boolean  @default(false)\n  // Pieces of the line on THIS machine — a sheet job's sheets, to the\n  // hundredth; null = whatever the other machines do not take. A line split\n  // over two machines is two rows.\n  qty       Float?\n  // The sheet of the item this machine cuts — \"<thickness>|<material>|<size>\"\n  // off the MATERIAL tab's nesting — when the item is spread over machines\n  // by sheet (its 3 mm on one laser, its 5 mm on another, at the same time).\n  // \"\" = the whole item, every sheet of it.\n  sheet     String   @default(\"\")\n  // Pieces' worth of THAT sheet cut so far on this machine — ✓ on a sheet's\n  // card line. The item itself is counted when it is recorded on the\n  // worklist; that recording takes the same pieces back off this figure.\n  sheetDone Int      @default(0)\n  setBy     String?\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([dept, bom, mo, item, machineId, sheet])\n  @@index([dept, bom, mo, item])\n  @@index([machineId])\n}\n\n// One department's floor as the planner drew it on the old Floor canvas —\n// positions and sizes of machine blocks, areas and labels, as one JSON blob.\n// The Floor screen is gone from the app; nothing reads or writes this table\n// any more, and it stays only until it is dropped.\nmodel FloorLayout {\n  id        Int      @id @default(autoincrement())\n  dept      String   @unique // Cut | Welding | ShotBlast | Painting\n  data      Json\n  updatedBy String?\n  updatedAt DateTime @default(now()) @updatedAt\n}\n\n// A named what-if scenario, saved through the assistant for everyone (\"the\n// emergency plan for order X\") — the knobs, the queue and the splits, as one\n// JSON blob.\nmodel SimScenario {\n  id        Int      @id @default(autoincrement())\n  name      String   @unique\n  data      Json\n  savedBy   String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n}\n\n// The APPROVED run order — the simulator scenario the admin committed to.\n// Every dept worklist shows its slice of this sequence until it is replaced\n// or cleared. batchQty marks a rushed split (\"first 10 of the TC\").\nmodel RunOrderEntry {\n  id        Int      @id @default(autoincrement())\n  rank      Int\n  mo        String\n  item      String\n  batchQty  Float?\n  batchNo   Int?\n  appliedAt DateTime @default(now())\n  appliedBy String?\n\n  @@index([mo])\n}\n\n// ---- Tank serial tracking (item TN) ----\n// Tanks are the first component tracked PIECE BY PIECE. HandoverEntry stays the\n// ledger's truth for quantities; the rows below are the per-piece layer on top,\n// so the two always agree in count. Every other component keeps working purely\n// on quantities.\n\n// A shop-floor worker: credited with a tank operation (welder, leak tester,\n// painter, QA inspector) and counted on the shift log of every department.\n// NOT an app account — the people on the floor rarely have logins. The admin\n// keeps this list in Admin → Workers.\nmodel Worker {\n  id Int @id @default(autoincrement())\n\n  // The number on the man's badge — what the shop floor TYPES to identify him.\n  // Names on this list repeat and are long to spell; the number does not, so it\n  // is the identifier everywhere and the name is only shown back to confirm it.\n  empId String @unique\n\n  name     String  @unique\n  jobTitle String? // Tank Full Welder, Welder Helper, Painter, … — as HR lists it\n  // The welder's STAMP: the letter he punches into every tank he welds. It is\n  // physically on the steel, so it is what ties a tank in the yard back to the\n  // man who made it, with or without the app.\n  stamp    String?\n\n  depts         String    @default(\"\") // CSV of section codes (lib/domain/tanks.ts WORKER_SECTIONS)\n  active        Boolean   @default(true) // inactive workers stay on old records, leave the dropdowns\n  // On vacation until this day (inclusive): out of the dropdowns until then,\n  // and kept absent when the shift log fills today's not-set workers in one\n  // click. Null = at work.\n  vacationUntil DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  shifts           ShiftEntry[]\n  consumableIssues ConsumableIssue[]\n  consumableShares ConsumableIssueRecipient[]\n\n  @@index([active])\n}\n\n// ONE physical tank, born at its first welding record and carried through\n// leak test → painting → the printed barcode sticker. The serial is the\n// factory-visible identity the technician writes on the steel:\n//   SF-<BOM>-<0001>   — the number restarts at 1 for every BOM.\n// Worker names are SNAPSHOTS: renaming or deleting a worker never rewrites\n// what a finished tank says about who made it.\nmodel TankUnit {\n  id     Int    @id @default(autoincrement())\n  serial String @unique\n  bom    String\n  mo     String\n  item   String @default(\"TN\")\n  seq    Int // the running number behind the serial (per BOM)\n  planNo Int    @default(0)\n\n  status String @default(\"welded\") // welded | repair | tested | painted (lib/domain/tanks.ts)\n\n  // The daily-log rows this tank belongs to. Without them, deleting a log row\n  // would leave the tank behind — still sitting in the barcode tab claiming a\n  // stage the ledger no longer records. Nullable because a row can be deleted\n  // out from under a tank, and because tanks made before this link existed\n  // fall back to matching by MO and status.\n  weldLedgerId  Int?\n  paintLedgerId Int?\n\n  weldedAt    DateTime\n  weldedById  Int?\n  weldedBy    String?\n  // The stamp punched into THIS tank — snapshotted at welding, like the name.\n  // Re-assigning a welder's stamp later must never change what an already\n  // finished tank says is on its steel.\n  weldedStamp String?\n  weldedLogBy String? // the app account that recorded the welding\n\n  // leak test — the LATEST attempt; every attempt is kept in TankEvent\n  testedAt   DateTime?\n  testedById Int?\n  testedBy   String?\n  testResult String? // pass | repair\n  testNote   String?\n\n  paintedAt   DateTime?\n  paintedById Int?\n  paintedBy   String?\n\n  // quality's verdict after scanning the printed barcode\n  qaAt     DateTime?\n  qaById   Int?\n  qaBy     String?\n  qaResult String? // ok | not-ok\n  qaNote   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  events TankEvent[]\n\n  @@unique([bom, seq])\n  @@index([weldLedgerId])\n  @@index([paintLedgerId])\n  @@index([mo, status])\n  @@index([status])\n  @@index([bom])\n}\n\n// Every state change a tank went through — its history on the tank page, kept\n// even after a later stage overwrites the summary fields above (a re-tested\n// tank keeps BOTH the failed and the passing test).\nmodel TankEvent {\n  id         Int      @id @default(autoincrement())\n  tankId     Int\n  kind       String // welded | repaired | leak-pass | leak-repair | painted | qa-ok | qa-not-ok\n  at         DateTime @default(now())\n  workerId   Int?\n  workerName String?\n  byUser     String? // the app account that recorded it\n  note       String?\n\n  tank TankUnit @relation(fields: [tankId], references: [id], onDelete: Cascade)\n\n  @@index([tankId])\n}\n\n// Per-BOM serial counter. Bumping this row inside the SAME transaction that\n// creates the tanks is what stops two technicians saving at the same moment\n// from ever minting the same serial.\nmodel TankSerialCounter {\n  bom  String @id\n  next Int    @default(1) // the number the NEXT tank of this BOM will take\n}\n\n// ---- MATERIAL — the planner's \"Nesting Tracker\" sheet, month by month ----\n\n// One line per month × BOM × material × thickness × sheet size — the sheet's\n// own row, carrying its typed columns: Quantity of Units, sheets ONE unit\n// needs, and the sheets actually nested for the job. The sheet's two formula\n// columns (sheets for the job, difference) are derived at read time, never\n// stored, so they cannot go stale or come back as #VALUE!.\n//\n// producedQty is the tab's own addition: how many units were actually made\n// so far. Against the sheet's actual-nesting rate it yields the sheets those\n// units really consumed — the number the planner asked for.\n//\n// month is the plan month the sheet was imported for (\"July 2026\", the same\n// label the monthly plan uses). It is part of the identity, so importing a\n// month's sheet again updates that month's lines instead of doubling them.\nmodel MaterialUsage {\n  id                  Int      @id @default(autoincrement())\n  // Which product line's nesting this is — TR or LV, stamped from the line on\n  // screen when the line is typed or its sheet imported. The tab shows one at a time.\n  line                String   @default(\"TR\")\n  month               String   @default(\"\") // \"\" = entered before months existed\n  bom                 String\n  mo                  String   @default(\"\") // \"\" = the line covers the BOM (how the sheet writes it)\n  units               Float    @default(0) // Quantity of Units\n  partCode            String   @default(\"\") // FB-022 — the part this line's sheets go into\n  partName            String   @default(\"\") // TANK, TOP COVER …\n  materialCode        String   @default(\"\") // the sheet's \"Codes\": T-SSS-5MM\n  material            String // Steel | Stainless steel | … (lib/domain/material.ts)\n  thicknessMm         Float\n  sheetSize           String // \"1220*2440\"\n  sheetsPerUnit       Float // No. of Sheets in BOM for one Unit\n  // \"No. of Sheets in Actual Nesting for one Unit\", STORED AS THE SHEET WRITES\n  // IT. It used to be derived back out of sheetsUsed ÷ units, which is a\n  // round trip through a rounded product: the figure shown was never quite the\n  // figure imported, and with no units on the line it vanished. Everything the\n  // tab multiplies — the job, a produced quantity — multiplies THIS.\n  actualPerUnit       Float?\n  // The rate was TYPED in the tab rather than read off the sheet. A re-import\n  // then leaves it alone: the planner types it for the lines the sheet does\n  // not carry, and a fresh sheet must never blank what he worked out.\n  actualPerUnitManual Boolean  @default(false)\n  sheetsUsed          Float? // No. of Sheets in Actual Nesting for Job — blank until nested\n  producedQty         Float? // units actually produced so far — the daily entry\n  // The line's row in the sheet it came from, so the tab reads in the sheet's\n  // own order rather than alphabetically. Lines typed in the tab sort last.\n  sortOrder           Int      @default(0)\n  // The newer sheet's own columns: the SOI it files the MO under, the weight\n  // of one sheet (kg — the actual weight is that × the pieces nested for the\n  // job), and the planner's average utilization of the nesting.\n  soi                 String   @default(\"\")\n  // the newest sheet's first column: the MTR request the sheets were drawn on\n  mtr                 String   @default(\"\")\n  weightKg            Float?\n  utilization         Float?\n  note                String?\n  recordedBy          String?\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  @@unique([month, bom, mo, partCode, material, thicknessMm, sheetSize])\n  @@index([bom])\n  @@index([month])\n  @@index([line])\n}\n\n// ---- ODOO close-out log (the planner's daily \"22\" sheet) ----\n\n// One row per Odoo manufacturing order the office tried to close on a day,\n// with what happened: \"Done\", or the stock error Odoo threw back. A retried\n// close on a later day is a NEW row — the log records attempts, not orders,\n// which is why nothing here is unique.\n//\n// odooMo is Odoo's own MO number (SF01/MO/…), a different series from the\n// plan's MOs (PF01/MO/…), so the row stands on its own rather than linking\n// to the orders registry.\nmodel OdooEntry {\n  id         Int       @id @default(autoincrement())\n  // Which product line's close-out this is — TR or LV. Stamped from the\n  // line picked when the row is typed or imported, from the order when it is born\n  // of a closing. The tab shows one line at a time.\n  line       String    @default(\"TR\")\n  date       DateTime // the day of the attempt (day-only granularity)\n  soi        String?\n  fgCode     String // FB-022-14003E11M11 — Odoo's finished-good code\n  product    String // Tank | Top Cover | Core Frame | Encloser | Cable Box …\n  odooMo     String // SF01/MO/06234\n  qty        Float\n  status     String    @default(\"MO to be close\") // MO to be close | Pending | Done | Blocked | Cancelled …\n  doneAt     DateTime? // when the status was moved to Done; null while it is not\n  recordedBy String?\n  // Where the row came from: typed (manual), the office's sheet (import), or\n  // born from a closing in the ledger — a painting row (painting) or the\n  // core's shot blast (shotblast). A born row carries its ledger entry's id\n  // and an EMPTY odooMo: Odoo's number is not ours to know, the clerk types it.\n  source     String    @default(\"manual\")\n  ledgerId   Int?      @unique\n  // The FG-CODE was composed (part code + BOM) rather than copied from an\n  // earlier row of the same SOI and product — worth a look before it is booked.\n  fgGuessed  Boolean   @default(false)\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  notes OdooNote[]\n\n  @@index([date])\n  @@index([doneAt])\n  @@index([odooMo])\n  @@index([line])\n}\n\n/// The notes on one close-out row, oldest first — what Odoo answered, what\n/// was done about it. The clerk enters the row; the planner adds the notes\n/// and moves the status, and can delete a note that no longer applies.\nmodel OdooNote {\n  id         Int       @id @default(autoincrement())\n  entryId    Int\n  entry      OdooEntry @relation(fields: [entryId], references: [id], onDelete: Cascade)\n  text       String\n  recordedBy String?\n  at         DateTime  @default(now())\n\n  @@index([entryId])\n}\n\n// ---- CONSUMABLES — what the store hands out to the shop floor ----\n\n// One row per hand-out: an item (typed freely — the store's own words), how\n// much, the department it went to and the worker who took it. The moment is\n// the server's clock at recording, never typed, so the log cannot be\n// back-dated. Once written, a row is changed only by the person who recorded\n// it (consumables.edit) or an admin, and every change keeps the row before\n// and after in ConsumableIssueRevision, from which an admin can restore any\n// earlier version. Delete is the admin's, and soft — the row leaves the log\n// but stays in the table with who removed it and when.\nmodel ConsumableIssue {\n  id             Int                        @id @default(autoincrement())\n  item           String\n  // decimal, not float: grease by the kilo and paint by the litre must add\n  // up exactly when the month is totalled\n  qty            Decimal                    @db.Decimal(14, 3)\n  // A worker section's code (WeldingTX, PaintingLV … — lib/domain/tanks.ts\n  // WORKER_SECTIONS), or a department typed by the recorder that is not one\n  // of them (Maintenance, Store …). Typed ones reappear in the dropdown.\n  department     String\n  // Who took it: one worker (workerId), or a group — several workers picked\n  // by name, or the whole department as it stood (the workers present in the\n  // section at recording). A group's people are ConsumableIssueRecipient;\n  // recipientCount is how many, kept as it was that day.\n  workerId       Int?\n  worker         Worker?                    @relation(fields: [workerId], references: [id], onDelete: Restrict)\n  recipientScope String                     @default(\"worker\") // worker | workers | department\n  recipientCount Int                        @default(1)\n  recipients     ConsumableIssueRecipient[]\n  notes          String?\n  issuedAt       DateTime                   @default(now())\n\n  // The catalogue item it was handed out of; null for an item typed by hand\n  // (not in the catalogue — no limit applies). `item` keeps the name either way.\n  itemId          Int?\n  catalog         ConsumableItem? @relation(fields: [itemId], references: [id], onDelete: Restrict)\n  // Recorded although it took a limit over (the recorder was warned and gave\n  // the reason); the breach as it read at that moment, for the record.\n  overLimit       Boolean         @default(false)\n  overLimitReason String?\n  overLimitNote   String?\n\n  // who typed it: the account (SetNull — accounts can be deleted) and the\n  // name as it was that day, so the record reads the same afterwards\n  recordedById   Int?\n  recordedByUser User?  @relation(fields: [recordedById], references: [id], onDelete: SetNull)\n  recordedBy     String\n\n  editedAt  DateTime?\n  editedBy  String?\n  deletedAt DateTime?\n  deletedBy String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  revisions ConsumableIssueRevision[]\n\n  // the log is always \"not deleted, in this period\"\n  @@index([deletedAt, issuedAt])\n  // the limit checks: one item's hand-outs in a window\n  @@index([itemId, issuedAt])\n  @@index([workerId])\n  @@index([department])\n  @@index([recordedById])\n}\n\n/// One change to a hand-out: who, when, and the row before and after — the\n/// audit trail the admin reads, and the versions an admin can restore.\nmodel ConsumableIssueRevision {\n  id      Int             @id @default(autoincrement())\n  issueId Int\n  issue   ConsumableIssue @relation(fields: [issueId], references: [id], onDelete: Cascade)\n  action  String // edit | delete | restore\n  // { item, qty, department, workerId, workerEmpId, workerName, notes }\n  before  Json\n  // the same shape after the change; null for a delete (nothing is left on\n  // the log) and for revisions written before this column existed\n  after   Json?\n  byId    Int?\n  by      String\n  at      DateTime        @default(now())\n\n  @@index([issueId])\n  // the admin's Edits view: every change in a period\n  @@index([at])\n}\n\n// ---- CONSUMABLES catalogue and limits ----\n\n/// What the store hands out: the item's code and name, its unit, and the\n/// limits on how much of it may go out. Never deleted once used — retired\n/// items are made inactive and leave the record form.\nmodel ConsumableItem {\n  id     Int     @id @default(autoincrement())\n  code   String? @unique // C-CON-DRB-04; the markers have none\n  name   String  @unique\n  uom    String  @default(\"PC\")\n  // the sheet's remark, kept as written (\"1 month\", \"Qty for one person\" …)\n  remark String?\n  active Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  limits ConsumableLimit[]\n  issues ConsumableIssue[]\n\n  @@index([active])\n}\n\n/// One limit on an item: `qty` per `period` for `departments`, counted as a\n/// `basis` — see lib/domain/consumableLimits.ts.\nmodel ConsumableLimit {\n  id          Int            @id @default(autoincrement())\n  itemId      Int\n  item        ConsumableItem @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  // \"*\" = every department, else a CSV of department keys (section codes or typed departments)\n  departments String\n  basis       String         @default(\"pool\") // pool | person\n  period      String         @default(\"week\") // day | week | month | quarter\n  qty         Decimal        @db.Decimal(14, 3)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([itemId])\n}\n\n/// Every change to the catalogue or a limit: who, when, and the thing before\n/// and after — so a limit that moved can always be traced.\nmodel ConsumableCatalogueChange {\n  id       Int      @id @default(autoincrement())\n  itemId   Int\n  entity   String // item | limit\n  entityId Int\n  action   String // create | update | delete\n  before   Json?\n  after    Json?\n  byId     Int?\n  by       String\n  at       DateTime @default(now())\n\n  @@index([itemId])\n  @@index([at])\n}\n\n/// The people of a group hand-out — several workers picked by name, or the\n/// whole department as it stood. Each counts an equal share of the quantity\n/// against a per-person limit.\n// How many workers each section had in a month — what a per-worker limit is\n// multiplied by when that month is reviewed later. Rewritten (the month's\n// rows replaced) whenever the workers list changes or a hand-out is\n// recorded, so the last write of a month is the month as it ended; a month\n// with no write reads the latest month before it. department \"*\" holds the\n// total, so a month whose sections all went empty is still a month on record.\nmodel ConsumableHeadcount {\n  month      String // \"2026-10\", the factory's calendar month\n  department String // a worker section's code, or \"*\"\n  workers    Int\n  updatedAt  DateTime @updatedAt\n\n  @@id([month, department])\n}\n\nmodel ConsumableIssueRecipient {\n  issueId  Int\n  issue    ConsumableIssue @relation(fields: [issueId], references: [id], onDelete: Cascade)\n  workerId Int\n  worker   Worker          @relation(fields: [workerId], references: [id], onDelete: Restrict)\n\n  @@id([issueId, workerId])\n  @@index([workerId])\n}\n\n/// POWDER SCRAP — the powder-coating powder the painting lines throw away\n/// (overspray that is not reclaimed, contaminated or expired powder), weighed\n/// in kg and recorded per painting section and day. The month's scrap is set\n/// against the powder the store handed out to that section (the consumables\n/// hand-outs of catalogue items named \"…Powder…\") — the scrap rate. Soft\n/// delete, every change kept in PowderScrapRevision.\nmodel PowderScrap {\n  id             Int       @id @default(autoincrement())\n  /// The factory day the scrap was weighed (chosen — it is often weighed after the shift).\n  day            DateTime  @db.Date\n  department     String // PaintingTX | PaintingLV\n  kg             Decimal   @db.Decimal(12, 3)\n  notes          String?\n  recordedById   Int?\n  recordedByUser User?     @relation(fields: [recordedById], references: [id], onDelete: SetNull)\n  recordedBy     String\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  editedAt       DateTime?\n  editedBy       String?\n  deletedAt      DateTime?\n  deletedBy      String?\n\n  revisions PowderScrapRevision[]\n\n  @@index([deletedAt, day])\n}\n\nmodel PowderScrapRevision {\n  id      Int         @id @default(autoincrement())\n  scrapId Int\n  scrap   PowderScrap @relation(fields: [scrapId], references: [id], onDelete: Cascade)\n  action  String // edit | delete | restore\n  before  Json\n  after   Json?\n  byId    Int?\n  by      String\n  at      DateTime    @default(now())\n\n  @@index([scrapId])\n  @@index([at])\n}\n\n// PHYSICAL MATERIAL — the store's count against SF01's stock in Odoo, one\n// row per Odoo product code. One living table: importing the store's sheet\n// again updates each code's row, never doubles it (lib/domain/physicalStock.ts).\nmodel PhysicalStock {\n  id        Int      @id @default(autoincrement())\n  code      String   @unique // Odoo's product code, as the sheet writes it\n  name      String   @default(\"\")\n  uom       String   @default(\"\") // PC | KG …\n  physical  Float    @default(0) // counted in the internal store\n  odoo      Float    @default(0) // SF01's stock in Odoo\n  sortOrder Int      @default(0) // the sheet's own row order\n  note      String?\n  updatedBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// A job put on a machine that the plan does not carry — a repair, a sample,\n// a spare part, anything the floor is asked for outside the monthly plan.\n// Typed on the machine board, it queues on its machine like any plan line\n// (on the board as BOM \"MANUAL\", MO \"MANUAL-<id>\", item \"JOB\" — the key the\n// machine queue rows carry), and is KEPT: done or not, the list stays to come\n// back to. Its output is recorded here, never in the plan's ledger — it is\n// no order's work.\n//\n// On the fabrication board a job is a SHEET JOB (bySheet): sheets of one\n// thickness, material and size, carrying the parts of several projects\n// (ManualJobPart). Its qty and doneQty then count SHEETS — the machines\n// close it sheet by sheet — and the parts are what the technician cuts from\n// them, never recorded in the plan's ledger by it.\nmodel ManualJob {\n  id          Int             @id @default(autoincrement())\n  dept        String // Cut | Welding | Painting | ShotBlast — the board it was typed on\n  title       String // what it is, in the planner's words (\"\" on a sheet job: its sheet names it)\n  bom         String          @default(\"\") // a BOM it belongs to, when there is one\n  item        String          @default(\"\") // the part, when there is one (Tank, bracket…)\n  // pieces wanted and done — or, on a sheet job, sheets wanted and cut,\n  // to the hundredth of a sheet (2.5); pieces stay whole\n  qty         Float\n  doneQty     Float           @default(0)\n  bySheet     Boolean         @default(false)\n  parts       ManualJobPart[]\n  // the sheet it is cut from, typed with it — the same facts the nesting\n  // gives a plan line: thickness, material, sheet size, sheets for the job\n  material    String    @default(\"\")\n  thicknessMm Float?\n  sheetSize   String    @default(\"\")\n  sheets      Float?\n  note        String?\n  // the machine it was last put on — kept when it comes off, for the record\n  machineId   Int?\n  machine     Machine?  @relation(fields: [machineId], references: [id], onDelete: SetNull)\n  createdBy   String?\n  createdAt   DateTime  @default(now())\n  doneAt      DateTime?\n  updatedAt   DateTime  @updatedAt\n\n  @@index([dept])\n  @@index([machineId])\n}\n\n// One project's part on a sheet job's sheets: the project (BOM), its\n// component (TN, TC, CF …), the part in the planner's words (Bottom, Side\n// wall, Skirt base …) and how many pieces the job's sheets carry of it —\n// null when the planner did not give the count.\nmodel ManualJobPart {\n  id    Int       @id @default(autoincrement())\n  jobId Int\n  job   ManualJob @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  bom   String    @default(\"\")\n  item  String    @default(\"\")\n  part  String\n  pcs   Int?\n\n  @@index([jobId])\n  @@index([bom])\n}\n\n// Every ✓ on a sheet's line on a machine card: which sheet (thickness,\n// material, size) of which item was cut on which machine, how many pieces'\n// worth, and when. The board's own figure (WorklistMachine.sheetDone) is\n// taken back off once the item is recorded; this log keeps it — the history\n// of what each machine cuts at what thickness, for planning machines from it.\n// A sheet job's ✓ writes here too — under its board key (BOM \"MANUAL\", MO\n// \"MANUAL-<id>\", item \"JOB\"), qty = the SHEETS cut on that machine (2.5).\nmodel SheetCutLog {\n  id          Int      @id @default(autoincrement())\n  at          DateTime @default(now())\n  date        DateTime // the factory day it was cut on\n  dept        String\n  bom         String\n  mo          String\n  item        String\n  sheet       String // \"<thickness>|<material>|<size>\"\n  thicknessMm Float?\n  machineId   Int?\n  machine     Machine? @relation(fields: [machineId], references: [id], onDelete: SetNull)\n  qty         Float\n  createdBy   String?\n\n  @@index([machineId])\n  @@index([item])\n  @@index([date])\n}\n\n// A NEST RUN — sheets of one material, thickness and size put on a cutting\n// machine, the nesting on them carrying parts of SEVERAL jobs at once (the\n// tank of one order beside the top cover of another, all 3 mm). On the\n// board it queues like any line (BOM \"RUN\", MO \"RUN-<id>\", item \"SHEET\" —\n// the key its machine-queue row carries); the technician records it by the\n// sheets finished, and each part's pieces follow pro rata.\n// No longer made: the fabrication board's sheet jobs (ManualJob, bySheet)\n// took their place. The rows stay as the record of what was cut.\nmodel NestRun {\n  id           Int           @id @default(autoincrement())\n  dept         String        @default(\"Cut\")\n  material     String\n  thicknessMm  Float\n  sheetSize    String        @default(\"\")\n  sheets       Int\n  sheetsDone   Int           @default(0)\n  // The cutting time, in minutes: identical sheets carry ONE figure (a sheet's\n  // time, the run's being that × sheets); different sheets carry one per\n  // sheet, in the order they are cut. Empty = not given (the parts' standard\n  // times stand in).\n  identical    Boolean       @default(true)\n  sheetMinutes Float[]       @default([])\n  note         String?\n  createdBy    String?\n  createdAt    DateTime      @default(now())\n  doneAt       DateTime?\n  updatedAt    DateTime      @updatedAt\n  parts        NestRunPart[]\n\n  @@index([dept])\n}\n\n// One job's part inside a nest run: how many pieces of it the run's sheets\n// carry, how many are cut so far (from the sheets finished), and how many of\n// those the item's Cut record has already counted.\nmodel NestRunPart {\n  id          Int     @id @default(autoincrement())\n  runId       Int\n  run         NestRun @relation(fields: [runId], references: [id], onDelete: Cascade)\n  bom         String\n  mo          String\n  item        String\n  pcs         Int\n  donePcs     Int     @default(0)\n  consumedPcs Int     @default(0)\n  // A part cut from a sheet its nesting does not use — a 4 mm instead of its\n  // 3 mm: the item's sheet this one stands in for (\"<thk>|<material>|<size>\"),\n  // so the item counts as cut on it. \"\" = the run's own sheet is the item's.\n  replaces    String  @default(\"\")\n\n  @@index([runId])\n  @@index([bom, mo, item])\n}\n\n// ---- The AI assistant (the AI tab): Claude answering from this database ----\n//\n// It reads the database through its own Postgres login, ai_reader, which can\n// only SELECT — and not from the accounts, sessions, chat, preferences or the\n// assistant's own tables (see the ai_assistant migration). A table added\n// later is readable by it automatically; one holding anything private must be\n// revoked from ai_reader in the migration that creates it.\n\n// The watchdog's settings (one row): each working morning from `at`, it looks\n// for orders heading late, output under its usual and absence, and sends what\n// it found to the people listed (none: the owner). lastRunISO claims the day,\n// so a busy scheduler never runs it twice.\nmodel WatchSettings {\n  id           Int       @id @default(1)\n  enabled      Boolean   @default(true)\n  at           String    @default(\"07:15\")\n  dropPct      Int       @default(30)\n  absencePct   Int       @default(15)\n  chronicDays  Int       @default(3)\n  chronicOf    Int       @default(5)\n  lateMinDays  Int       @default(1)\n  recipientIds Int[]     @default([])\n  // a few lines by the assistant over the findings (Haiku; costs a little)\n  aiSummary    Boolean   @default(true)\n  lastRunISO   String?\n  lastRunAt    DateTime?\n  lastFindings Int       @default(0)\n  updatedBy    String?\n  updatedAt    DateTime  @updatedAt\n}\n\n// One thing the watchdog found on one day — kept so a re-run says nothing\n// twice, the assistant can read the week's findings, and a finding turned\n// into a task remembers it.\nmodel WatchFinding {\n  id        Int      @id @default(autoincrement())\n  dayISO    String\n  key       String\n  kind      String // late | output | absence\n  severity  String // critical | warn\n  title     String\n  detail    String\n  mo        String?\n  createdAt DateTime @default(now())\n\n  @@unique([dayISO, key])\n  @@index([createdAt])\n}\n\n// The cockpit's figures as they read on a factory day — kept so the trend of\n// what cannot be recomputed later (how many plan lines were late THAT day,\n// the welding coverage then) survives. One row a day, rewritten while the day\n// lasts; the shape is lib/domain/kpis.ts KpiSnapshotData.\nmodel KpiSnapshot {\n  id        Int      @id @default(autoincrement())\n  date      DateTime @unique @db.Date\n  data      Json\n  updatedAt DateTime @default(now()) @updatedAt\n}\n";
